<style>
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
:root{
  --primary-dark:#171717;
  --accent-blue:#0072F5;
  --bg-light:#FAFAFA;
  --border:#E5E5E5;
  --text-secondary:#6B7280;
  --card-shadow:0 1px 3px rgba(0,0,0,.08);
