.nav-item.has-dropdown.open::after{transform:rotate(180deg)}
.header-actions{display:flex;align-items:center;gap:8px}
.btn-ghost{padding:8px 14px;font-size:14px;font-weight:500;border-radius:6px;transition:background var(--transition)}
.btn-ghost:hover{background:#f3f4f6}
.btn-primary{padding:8px 18px;font-size:14px;font-weight:600;border-radius:6px;background:var(--primary-dark);color:#fff;transition:opacity var(--transition)}
.btn-primary:hover{opacity:.85}
.btn-accent{background:var(--accent-blue);color:#fff}
.btn-accent:hover{opacity:.85}

/* Mega Menu */
.mega-menu{display:none;position:absolute;top:100%;left:50%;transform:translateX(-50%);background:#fff;border:1px solid var(--border);border-radius:var(--radius-lg);box-shadow:0 12px 40px rgba(0,0,0,.12);padding:28px 32px;min-width:560px;z-index:200}
