.mega-menu-col a{display:block;padding:6px 0;font-size:14px;font-weight:500;transition:color var(--transition)}
.mega-menu-col a:hover{color:var(--accent-blue)}
.mega-menu-col .sub{display:block;font-size:12px;color:var(--text-secondary);font-weight:400;margin-top:1px}

