.featured-card p{font-size:14px;line-height:1.6;opacity:.8;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
.featured-card .card-stats{display:flex;gap:16px;margin-top:16px;flex-wrap:wrap}
.featured-card .stat{background:rgba(255,255,255,.15);backdrop-filter:blur(4px);border-radius:6px;padding:8px 14px;font-size:13px;font-weight:600}
