/* ─── RESPONSIVE ─── */
@media(max-width:1024px){
  .featured-grid{grid-template-columns:1fr 1fr}
  .featured-grid .featured-card:last-child{grid-column:1/-1}
  .news-grid{grid-template-columns:1fr 1fr}
