const INITIAL_COUNT = 8;
const LOAD_MORE_COUNT = 6;
let visibleCount = INITIAL_COUNT;
let activeCategory = "all";
let searchQuery = "";

function getTagClass(category) {
  const map = { customers: "tag-customers", engineering: "tag-engineering" };
  return map[category] || "tag-general";
}

function getCategoryLabel(category) {
  const map = {
    general: "General",
    customers: "Customers",
    engineering: "Engineering",
    community: "Community",
    "company-news": "Company News",
    v0: "v0",
    security: "Security",
    changelog: "Changelog",
    press: "Press"
  };
  return map[category] || category;
}

function createCard(post) {
  return `<article class="news-card" data-category="${post.category}">
    <span class="card-tag ${getTagClass(post.category)}">${getCategoryLabel(post.category)}</span>
    <span class="card-date">${post.date}</span>
    <h3>${post.title}</h3>
    <p>${post.excerpt}</p>
    <div class="card-author">
      <div class="avatar">${post.initials}</div>
      <span class="author-name">${post.author}</span>
    </div>
  </article>`;
}

function getFilteredPosts() {
  return allPosts.filter(post => {
    const catMatch = activeCategory === "all" || post.category === activeCategory;
    const q = searchQuery.toLowerCase();
    const searchMatch = !q ||
      post.title.toLowerCase().includes(q) ||
      post.excerpt.toLowerCase().includes(q) ||
      post.author.toLowerCase().includes(q) ||
      post.category.toLowerCase().includes(q);
    return catMatch && searchMatch;
  });
}

function render() {
  const filtered = getFilteredPosts();
  const toShow = filtered.slice(0, visibleCount);
  const grid = document.getElementById("newsGrid");
  const noResults = document.getElementById("noResults");
  const showMoreWrap = document.getElementById("showMoreWrap");
  const featuredSection = document.getElementById("featuredSection");

  grid.innerHTML = toShow.map(createCard).join("");

  // Featured visibility
  const showFeatured = activeCategory === "all" && !searchQuery;
  featuredSection.style.display = showFeatured ? "" : "none";

  // No results
  if (filtered.length === 0) {
    noResults.classList.add("visible");
    showMoreWrap.style.display = "none";
  } else {
    noResults.classList.remove("visible");
    showMoreWrap.style.display = visibleCount < filtered.length ? "" : "none";
  }
}

// Category pills
document.querySelectorAll(".filter-pill").forEach(pill => {
  pill.addEventListener("click", () => {
    document.querySelectorAll(".filter-pill").forEach(p => p.classList.remove("active"));
    pill.classList.add("active");
    activeCategory = pill.dataset.category;
    visibleCount = INITIAL_COUNT;
    render();
  });
});

// Search
document.getElementById("searchInput").addEventListener("input", (e) => {
  searchQuery = e.target.value;
  visibleCount = INITIAL_COUNT;
  render();
});

// Show more
document.getElementById("showMoreBtn").addEventListener("click", () => {
  visibleCount += LOAD_MORE_COUNT;
  render();
});

// Dropdowns
document.querySelectorAll(".nav-item.has-dropdown").forEach(item => {
  item.addEventListener("click", (e) => {
    e.stopPropagation();
    const id = "dropdown-" + item.dataset.dropdown;
    const menu = document.getElementById(id);
    const isOpen = menu.classList.contains("open");

    // Close all
    document.querySelectorAll(".mega-menu").forEach(m => m.classList.remove("open"));
    document.querySelectorAll(".nav-item.has-dropdown").forEach(n => n.classList.remove("open"));

    if (!isOpen) {
      menu.classList.add("open");
      item.classList.add("open");
    }
  });
});

document.addEventListener("click", () => {
  document.querySelectorAll(".mega-menu").forEach(m => m.classList.remove("open"));
  document.querySelectorAll(".nav-item.has-dropdown").forEach(n => n.classList.remove("open"));
});

document.querySelectorAll(".mega-menu").forEach(m => {
  m.addEventListener("click", e => e.stopPropagation());
});

